//! Regression oracles generated by tools/bench/gen_fixtures.py using the local
//! Applio definitions, torch/torchaudio CPU and CPUExecutionProvider RMVPE.
//! Run: cargo test -p engine --release --test dsp_parity -- --nocapture
use engine::dsp::{
    f0,
    mel::MelExtractor,
    resample::{Resampler, StreamResampler},
    sola::Sola,
};
use std::path::PathBuf;

fn fixture(name: &str) -> Vec<f32> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(format!("{name}.bin"));
    let bytes = std::fs::read(&path).unwrap_or_else(|e| {
        panic!(
            "reading {}: {e}; run tools/bench/gen_fixtures.py",
            path.display()
        )
    });
    assert_eq!(
        bytes.len() % 4,
        0,
        "{} is not an f32 fixture",
        path.display()
    );
    bytes
        .chunks_exact(4)
        .map(|b| f32::from_le_bytes(b.try_into().unwrap()))
        .collect()
}
fn assert_max_error(label: &str, got: &[f32], expected: &[f32], limit: f32) {
    assert_eq!(got.len(), expected.len(), "{label}: length mismatch");
    assert!(
        got.iter().chain(expected).all(|x| x.is_finite()),
        "{label}: nonfinite value"
    );
    let (index, error) = got
        .iter()
        .zip(expected)
        .enumerate()
        .map(|(i, (a, b))| (i, (a - b).abs()))
        .max_by(|a, b| a.1.total_cmp(&b.1))
        .unwrap();
    println!(
        "{label}: max_abs_error={error:.9e}, index={index}, got={:.9e}, reference={:.9e}, limit={limit:.9e}",
        got[index], expected[index]
    );
    assert!(
        error <= limit,
        "{label}: max absolute error {error:e} exceeds {limit:e} at {index}"
    );
}

#[test]
fn resample_48k_to_16k_parity() {
    let input = fixture("audio_48k");
    let got = Resampler::new(48000, 16000).process(&input);
    // A 41-tap dot product plus f64-generated -> f32 kernel versus Torch's
    // float32 kernel: a few f32 ULPs at PCM amplitudes, no audible tolerance.
    assert_max_error(
        "resample 48k->16k offline",
        &got,
        &fixture("resample_48k_16k"),
        5e-8,
    );
}
#[test]
fn resample_40k_to_48k_parity() {
    let input = fixture("audio_40k");
    let got = Resampler::new(40000, 48000).process(&input);
    // 19 taps per polyphase dot product; same precision budget as above.
    assert_max_error(
        "resample 40k->48k offline",
        &got,
        &fixture("resample_40k_48k"),
        5e-8,
    );
}
fn stream_parity(
    orig: u32,
    new: u32,
    label: &str,
    input_name: &str,
    expected_name: &str,
    width: usize,
    flush: usize,
) {
    let mut resampler = StreamResampler::new(orig, new);
    let input = fixture(input_name);
    let expected = fixture(expected_name);
    let mut got = Vec::new();
    for chunk in input.chunks(480) {
        got.extend(resampler.process(chunk));
    }
    got.extend(resampler.process(&vec![0.0; flush]));
    assert!(
        got.len() >= expected.len(),
        "tail flush must cover the complete delayed oracle"
    );
    got.truncate(expected.len());
    // Delay is in INPUT samples and is fractional in OUTPUT samples. Compare
    // against torchaudio([width zeros] + input), not an inaccurate integer shift.
    println!(
        "{label}: chunk=480, fixed_delay_input={width}, delay_output={:.9}, flush_input={flush}",
        width as f64 * new as f64 / orig as f64
    );
    assert_max_error(label, &got, &expected, 5e-8);
}
#[test]
fn stream_resample_48k_to_16k_parity() {
    stream_parity(
        48000,
        16000,
        "resample 48k->16k streaming",
        "audio_48k",
        "stream_48k_16k",
        19,
        21,
    );
}
#[test]
fn stream_resample_40k_to_48k_parity() {
    stream_parity(
        40000,
        48000,
        "resample 40k->48k streaming",
        "audio_40k",
        "stream_40k_48k",
        7,
        10,
    );
}
#[test]
fn rmvpe_log_mel_parity() {
    let basis = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/mel_basis.bin");
    let mut extractor = MelExtractor::new(&basis).unwrap();
    let (got, frames) = extractor.log_mel(&fixture("resample_48k_16k"));
    assert_eq!(frames, 51);
    // Different f32 FFTs, Hann generation and 513-bin accumulation, followed by
    // ln amplification near the 1e-5 clamp. 5e-5 natural-log units (~0.00043 dB)
    // is tight enough to detect STFT/reflect-pad/filterbank convention changes.
    assert_max_error("RMVPE log-mel", &got, &fixture("log_mel"), 5e-5);
}
#[test]
fn rmvpe_decode_parity() {
    let salience = fixture("salience");
    assert_eq!(salience.len() % f0::CLASSES, 0);
    let frames = salience.len() / f0::CLASSES;
    assert_eq!(frames, 59); // 51 actual CPU-model frames + 8 edge/threshold cases.
    let got = f0::decode(&salience, frames, 0.03);
    // NumPy reference uses float64 cents_mapping; Rust accumulates 9 float32
    // terms and powf. 0.002 Hz (<0.1 cent at normal speech pitch) covers these
    // arithmetic differences, while voiced/unvoiced decisions must match exactly.
    let expected = fixture("f0");
    assert_eq!(
        got.iter().map(|x| *x > 0.0).collect::<Vec<_>>(),
        expected.iter().map(|x| *x > 0.0).collect::<Vec<_>>()
    );
    assert_max_error("RMVPE decode Hz", &got, &expected, 2e-3);
}
#[test]
fn coarse_pitch_parity() {
    let input = fixture("coarse_input");
    let got: Vec<_> = input.into_iter().map(|x| f0::coarse(x) as f32).collect();
    // Embedding indices are discrete: no error tolerance is appropriate.
    assert_max_error("RVC coarse pitch bucket", &got, &fixture("coarse"), 0.0);
}
fn phase_vocoder_parity(n: usize) {
    let a = fixture(&format!("pv_{n}_a"));
    let b = fixture(&format!("pv_{n}_b"));
    let expected = fixture(&format!("pv_{n}_out"));
    assert_eq!(a.len(), n);
    let mut sola = Sola::new(n, 0, true);
    let mut onset = vec![0.0; n];
    onset.extend_from_slice(&a); // first process stores a as the previous tail
    let _ = sola.process(&onset, n);
    let mut current = b;
    current.resize(2 * n, 0.0);
    let got = sola.process(&current, n);
    assert_eq!(sola.last_offset(), 0);
    // Torch computes the n x bins synthesis phase in f32; Rust rotates bins in
    // f64 after a different f32 FFT. 8e-5 FS is well below waveform level and
    // detects wrong phase wrapping/DC/Nyquist weighting/window normalization.
    assert_max_error(
        &format!("phase vocoder n={n}"),
        &got,
        &expected,
        if n == 2400 { 8e-5 } else { 1e-6 },
    );
}
#[test]
fn phase_vocoder_even_parity() {
    phase_vocoder_parity(2400);
}
#[test]
fn phase_vocoder_odd_parity() {
    phase_vocoder_parity(511);
}
